import { defineConfig } from "oxlint";
import antiSlop from "ultracite/oxlint/anti-slop";
import core from "ultracite/oxlint/core";
import react from "ultracite/oxlint/react";

/** Generated or vendored trees we do not author. Mirrored in `oxfmt.config.ts`. */
const NOT_OURS = [
  ".agents/**",
  ".claude/**",
  "crates/**",
  "tests/**",
  // Generated by `bunx shadcn add`, rewritten on every `bun run upgrade`.
  "packages/ui/src/components/**",
  "packages/ui/src/hooks/**",
  "packages/ui/src/lib/**",
  // Generated from the Rust protocol, core and server crates.
  "packages/view-core/src/*.gen.ts",
  "apps/inspector/test/fixtures/**",
  // The npm wrapper runs on any Node the user has, as plain CommonJS.
  "scripts/release/npm/**",
];

export default defineConfig({
  extends: [core, react, antiSlop],
  ignorePatterns: [...core.ignorePatterns, ...NOT_OURS],
  overrides: [
    {
      files: ["scripts/**/*.ts"],
      rules: {
        // Bun's `$` returns a chainable ShellPromise. Marking these builders
        // `async` collapses it to a plain promise and loses `.cwd()`.
        "typescript/promise-function-async": "off",
      },
    },
    {
      files: ["**/*.{test,spec}.{ts,tsx}"],
      rules: {
        "no-magic-numbers": "off",
      },
    },
  ],
  rules: {
    // `import * as X` is the documented shape for several dependencies.
    "import/no-namespace": "off",
    // Logging is the point in scripts.
    "no-console": "off",
    // 0/1/-1 are self-describing; Biome's `noMagicNumbers` exempted them too.
    "no-magic-numbers": ["warn", { ignore: [-1, 0, 1] }],
    // Each workspace package exposes its public surface through a barrel.
    "oxc/no-barrel-file": "off",
    "typescript/consistent-type-definitions": ["error", "interface"],
  },
});
